#include "EmailContentBuilder.h"

#include <QSet>
namespace PN::Comm {
EmailPreparationResult EmailContentBuilder::prepare(const EmailPreparation &p){EmailPreparationResult r;auto source=validate(p.source);r.validation.issues+=source.issues;if(p.operationId.isNull())r.validation.addError("operation-id-required","operationId");if(p.document.workflow!=p.source.workflow)r.validation.addError("report-workflow-mismatch","document.workflow");if(p.mode==EmailMode::None){r.noEmail=true;return r;}if(p.document.defaultSubject.trimmed().isEmpty())r.validation.addError("email-subject-required","subject");if(p.document.defaultSubject.contains('\r')||p.document.defaultSubject.contains('\n'))r.validation.addError("email-header-injection","subject");QSet<QString> recipientAddresses;for(const auto &recipient:p.recipients){const QString address=recipient.address.trimmed();if(address.isEmpty()||address.contains('\r')||address.contains('\n')||address.contains(',')||address.contains(';')||!address.contains('@')){r.validation.addError("recipient-address-invalid","recipients");continue;}if(recipient.role<RecipientRole::To||recipient.role>RecipientRole::Bcc){r.validation.addError("recipient-role-invalid","recipients");continue;}const QString folded=address.toCaseFolded();if(recipientAddresses.contains(folded)){r.validation.addError("recipient-address-duplicate","recipients");continue;}recipientAddresses.insert(folded);}if(recipientAddresses.isEmpty()&&!p.addressLater)r.validation.addError("recipient-required","recipients");if(p.mode==EmailMode::InlineHtml&&p.document.emailFragment.trimmed().isEmpty())r.validation.addError("email-body-required","document");if(p.mode==EmailMode::HtmlAttachment||p.mode==EmailMode::PdfAttachment){const QString expected=p.mode==EmailMode::HtmlAttachment?"text/html":"application/pdf";bool found=false;for(const auto&a:p.attachments)if(a.mimeType==expected&&!a.absolutePath.isEmpty())found=true;if(!found)r.validation.addError("email-attachment-required","attachments");}if(!r.validation.ok())return r;EmailRequest q;q.operationId=p.operationId;q.source=p.source;q.previewRevision=p.previewRevision;q.backend=p.backend;q.accountKey=p.accountKey;q.accountGeneration=p.accountGeneration;q.recipients=p.recipients;q.subject=p.document.defaultSubject;q.plainText=p.document.plainText;q.attachments=p.attachments;q.addressLaterExplicitlyChosen=p.addressLater;if(p.mode==EmailMode::InlineHtml)q.html=p.document.emailFragment;r.request=q;return r;}
}
